import timeAgo from "../../libs/timeago"

type Drafts = {
    [key: string]: string,
};

type Data = {
    [key: string]: any;
}

export default abstract class DraftMessage
{
    private autoSaveTimer: any;
    private autoSaveTime: number = 30000;
    private autoSaveDisabled: boolean = false;
    private drafts: Drafts = {};

    protected constructor() {
        for (const id of this.getTextEditors()) {
            this.drafts[id] = '';
        }

        this.registerListeners();
    }

    abstract getTextEditors(): string[];
    abstract saveDraft($form: JQuery<HTMLElement>, useBeacon: boolean): void;
    abstract getStoreRoute(): string;
    abstract getDiscardRoute(): string;
    abstract getDiscardData($form: JQuery<HTMLElement>): {};

    getDrafts(): Drafts {
        return this.drafts;
    };

    setDraft (key: string, value: string): void {
        this.drafts[key] = value;
    };

    draftHasChanged (key: string, new_value: string): boolean {
        if (! this.drafts.hasOwnProperty(key)) {
            return false;
        }

        new_value = DraftMessage.normaliseMessage(new_value);

        return DraftMessage.normaliseMessage(this.drafts[key]) !== new_value && new_value !== '';
    };

    /**
     * Toggle the parts of the control that only apply while a draft is stored on the server, and
     * bring the rest of it back in step.
     */
    setHasDraft($form: JQuery<HTMLElement>, hasDraft: boolean): void {
        $form.find('.discard-draft, .draft-success, .sp-draft-icon').toggleClass('sp:hidden', ! hasDraft);

        this.refreshDraftOptions($form);
    };

    /**
     * The draft controls only apply once a draft exists or the message has been changed - until
     * then there's nothing to save or discard, so the whole control is hidden. Saving stays
     * available for as long as they're shown, it's also how an updated draft is stored.
     */
    refreshDraftOptions($form: JQuery<HTMLElement>): void {
        // Nothing to do for forms without draft controls, e.g. editing an existing message.
        const $options = $form.find('.sp-draft-options');
        if ($options.length === 0) {
            return;
        }

        const editorId = $form.find('textarea:not(.CodeMirror textarea)').eq(0).attr('id'),
            editor = typeof editorId === 'string' ? tinymce.get(editorId) : null,
            $discard = $form.find('.discard-draft').first();

        const hasDraft = $discard.length > 0 && ! $discard.hasClass('sp:hidden');
        // The same test auto-save uses, so the controls appear as soon as there's something to save.
        const hasChanges = !! editor
            && this.draftHasChanged(<string> editorId, editor.getContent({withoutCursorMarker: true}));

        $options.toggleClass('sp:hidden', ! hasDraft && ! hasChanges);
    };

    addAttachmentsToData($form: JQuery<HTMLElement>, data: Data) {
        // Add attachments to AJAX data.
        $form.find('input[name^="attachment["]:not(:disabled)').serializeArray().forEach(function (obj) {
            data[obj.name] = obj.value;
        });

        return data;
    }

    storeDraftUsingBeacon(data: Data) {
        if (! ("sendBeacon" in navigator)) {
            return;
        }

        navigator.sendBeacon(this.getStoreRoute(), new URLSearchParams($.param(data)));
    }

    storeDraftUsingAjax($form: JQuery<HTMLElement>, data: Data) {
        const instance = this;

        return $.post(this.getStoreRoute(), data)
            .then(function (response) {
                if (typeof response.status !== 'undefined' && response.status == 'success') {
                    // Update the saved message
                    $form.find('.draft-success').html(response.message);

                    // Refresh timeago.
                    if (typeof timeAgo !== 'undefined') {
                        timeAgo.render($('time.timeago'));
                    }

                    // Show saved message, discard button and draft icon
                    instance.setHasDraft($form, true);

                    // Add attachment-id data to each attachment.
                    var attachments = response.data.attachments;
                    for (var upload_hash in attachments) {
                        if (!attachments.hasOwnProperty(upload_hash)) {
                            continue;
                        }

                        var id = attachments[upload_hash];
                        $form.find('.sp-delete-attachment').each(function () {
                            if ($(this).data('hash') === upload_hash || $(this).prop('data-hash') === upload_hash) {
                                $(this).data('attachment-id', id);
                            }
                        });
                    }
                }
            })
    }

    discardDraft($form: JQuery<HTMLElement>): IPromise<{}> {
        // Post data to perform action
        const instance = this;

        // Delete any attachments currently showing
        $form.find('input[name="attachment[]"]:not(:first)').remove();
        $form.find('.sp-attached-files li:not(:first) .sp-delete-attachment')
            // @ts-ignore
            .attr('data-silent', true)
            .trigger('click');

        return $.post(instance.getDiscardRoute(), instance.getDiscardData($form))
            .then(function(response) {
                if (response.status == 'success') {
                    $('.sp-ticket-update.sp-alert-success').show(500).delay(5000).hide(500);

                    // Hide button, saved message and draft icon
                    instance.setHasDraft($form, false);
                } else {
                    $('.sp-ticket-update.sp-alert-error').show(500).delay(5000).hide(500);
                }

                return response;
            })
    }

    /**
     * Add &nbsp; to empty paragraphs so they don't get hidden in HTML.
     */
    static normaliseMessage (str: string): string {
        return str.replace('<p></p>', '<p>&nbsp;</p>');
    };

    autoSave(useBeacon: boolean): void
    {
        if (this.autoSaveTimer) {
            clearTimeout(this.autoSaveTimer);
        }

        // Don't run if auto-save is disabled (i.e. when storing a new message).
        if (this.autoSaveDisabled) {
            this.autoSaveTimer = setTimeout(this.autoSave.bind(this), this.autoSaveTime);

            return;
        }

        for (var editorId in this.drafts) {
            var $textarea = $('#'+editorId),
                $form = $textarea.parents('form');

            // Only if it's a tinymce editor
            if (! this.drafts.hasOwnProperty(editorId)
                || $form.find('.save-draft').length === 0
                || ! tinymce.get(editorId)
            ) {
                continue;
            }

            // Get the draft message.
            var draftMessage = this.drafts[editorId];

            // Check if message has changed
            var currentMessage = $textarea.editor().getContent({withoutCursorMarker: true});
            if (draftMessage === null || ! this.draftHasChanged(editorId, currentMessage)) {
                continue;
            }

            // Disable button while saving
            $form.find('.save-draft').prop('disabled', true);

            // Save draft
            this.saveDraft($form, useBeacon);

            // Re-enable button
            $form.find('.save-draft').prop('disabled', false);
        }

        // Delay the next poll by 30 seconds
        this.autoSaveTimer = setTimeout(this.autoSave.bind(this), this.autoSaveTime);
    }

    disableAutoSave(): void {
        this.autoSaveDisabled = true;
    }

    enableAutoSave(): void {
        this.autoSaveDisabled = false;
    }

    private registerListeners(): void
    {
        this.autoSave(false);

        // Before closing/redirecting away, check if there's a draft that needs to be saved.
        const instance = this;
        window.addEventListener('visibilitychange', function () {
            if (document.visibilityState === 'hidden') {
                instance.autoSave(true);
            }
        });

        const selector = Object.keys(this.drafts).map((v) => '#' + v).join(',');
        $(selector).on('loaded-editor-content', function (e, selector, $form, editor) {
            const editorId = $(selector).attr('id');
            if (typeof editorId !== 'string') {
                throw new Error('Invalid id attribute.');
            }

            instance.setDraft(editorId, editor.getContent({withoutCursorMarker: true}));
            instance.watchEditor($form, editor);
        });

        // Save draft button
        $('.save-draft').on('click', function(e) {
            instance.saveDraft($(this).parents('form'), false);
        });

        // Discard draft button
        $('.discard-draft').on('click', function() {
            instance.discardDraft($(this).parents('form'));
        });
    }

    /**
     * Keep the draft options in step with the message as it's edited.
     */
    private watchEditor($form: JQuery<HTMLElement>, editor: tinymce): void {
        // A re-initialised editor is a new instance, so this flag can't go stale.
        if ((<any> editor).spDraftWatched) {
            return;
        }

        (<any> editor).spDraftWatched = true;

        const instance = this;
        let timer: any;

        editor.on('input keyup change SetContent Undo Redo', function () {
            clearTimeout(timer);
            timer = setTimeout(function () {
                instance.refreshDraftOptions($form);
            }, 300);
        });

        this.refreshDraftOptions($form);
    }
}

