/**
 * Reply form header controls (sticky, minimise, maximise, resize)
 */
export default class ReplyFormControls {
    private isResizing: boolean = false;
    private form: JQuery<HTMLElement> | null = null;
    private startY: number = 0;
    private startHeight: number = 0;
    private touchId: number | null = null;
    private minHeight: number = 320;
    private defaultMaxHeight: string = 'calc(100vh - 6rem)';
    private storageKey: string = 'sp-reply-form-height';
    private stickyStorageKey: string = 'sp-reply-form-sticky';
    private replyOrder: string;

    constructor(replyOrder: string) {
        this.replyOrder = replyOrder;
        this.init();
    }

    private init(): void {
        this.initForm();
        this.attachEventListeners();
    }

    private initForm(): void {
        this.form = $('.ticket-reply-form');

        const isSticky = this.getStoredIsSticky();

        this.setSticky(isSticky);

        if (! isSticky) {
            // Height is only restricted while it's sticky.
            return;
        }

        // Restore stored height if available.
        const storedHeight = this.getStoredHeight();
        if (storedHeight && storedHeight >= this.minHeight) {
            this.setHeight(storedHeight);
        }
    }

    private attachEventListeners(): void {
        // Button clicks.
        $(document)
            .on('click', '.sp-reply-form-sticky', (e) => {
                e.preventDefault();
                this.setSticky($(e.currentTarget).attr('data-sticky') === 'true', true);
            })
            .on('click', '.sp-reply-form-minimise', (e) => {
                e.preventDefault();
                this.minimiseForm();
            })
            .on('click', '.sp-reply-form-maximise', (e) => {
                e.preventDefault();
                this.expandForm();
            })
            .on('click', '.sp-reply-form-resize', (e) => {
                e.preventDefault();
                this.compressForm();
            });

        // Resize handle. Touch scrolling is suppressed by touch-action on the handle itself, as
        // preventDefault() is ignored in the passive listeners the browser gives us on document.
        $(document).on('mousedown touchstart', '.sp-reply-form-resize-handle', (e) => {
            if (e.type === 'mousedown') {
                e.preventDefault();
            }

            e.stopPropagation();
            this.startResize(e);
        });

        // Resize move handlers.
        $(document)
            .on('mousemove.replyFormResize touchmove.replyFormResize', (e) => this.handleMove(e))
            .on('mouseup.replyFormResize touchend.replyFormResize touchcancel.replyFormResize', () => this.stopResize())
            .on('mouseleave.replyFormResize', () => {
                if (this.isResizing) {
                    this.stopResize();
                }
            })
            .on('keydown.replyFormResize', (e) => {
                if (e.key === 'Escape' && this.isResizing) {
                    this.stopResize();
                }
            })
            .on('contextmenu.replyFormResize', () => {
                if (this.isResizing) {
                    this.stopResize();
                }
            });

        $(window)
            .on('mouseup.replyFormResize', () => this.stopResize())
            .on('blur.replyFormResize', () => {
                if (this.isResizing) {
                    this.stopResize();
                }
            });

        $(document).on('visibilitychange.replyFormResize', () => {
            if (document.hidden && this.isResizing) {
                this.stopResize();
            }
        });
    }

    private setSticky(sticky: boolean, update: boolean = false): void {
        if (! this.form) {
            return;
        }

        const maxAllowedHeight = this.getMaxAllowedHeight();
        if (maxAllowedHeight) {
            this.defaultMaxHeight = maxAllowedHeight + 'px';
        }

        this.form.toggleClass('sp:sticky sp:z-50', sticky);
        this.form.find('.sp-reply-form-header').toggleClass('sp:sticky sp:top-0 sp:z-10002', sticky);
        this.form.find('.sp-reply-form-resize-handle').toggleClass('sp:hidden', ! sticky);

        // Leave the operator the button for the state they're not in.
        this.form.find('.sp-reply-form-sticky[data-sticky="true"]').toggleClass('sp:hidden', sticky);
        this.form.find('.sp-reply-form-sticky[data-sticky="false"]').toggleClass('sp:hidden', ! sticky);

        if (sticky) {
            this.toggleExpandControls(false);
        } else {
            this.form.find('.sp-reply-form-maximise, .sp-reply-form-resize').addClass('sp:hidden');
        }

        // Position it relative to the messages.
        const afterMessages = sticky || this.replyOrder === 'ASC';
        this.form
            .toggleClass('sp:mt-6', afterMessages)
            .toggleClass('sp:order-first sp:mt-0 sp:mb-6 sp:border-b', ! afterMessages);

        if (! sticky) {
            // Clear height restrictions.
            this.form.css({'height': 'auto', 'max-height': 'none'});
        }

        if (update) {
            // Store sticky state.
            this.setStoredIsSticky(sticky);

            if (sticky) {
                // Restore stored height if available and it's sticky.
                const storedHeight = this.getStoredHeight();
                if (storedHeight && storedHeight >= this.minHeight) {
                    this.setHeight(storedHeight);
                }
            } else {
                // scroll to the form if it's not visible
                this.form[0].scrollIntoView({behavior: 'smooth'});
            }
        }
    }

    /**
     * The maximise and resize buttons are mutually exclusive — only one applies at a time.
     */
    private toggleExpandControls(expanded: boolean): void {
        if (! this.form) {
            return;
        }

        this.form.find('.sp-reply-form-maximise').toggleClass('sp:hidden', expanded);
        this.form.find('.sp-reply-form-resize').toggleClass('sp:hidden', ! expanded);
    }

    private minimiseForm(): void {
        if (! this.form) {
            return;
        }

        // Hide directly rather than through the per-type toggles, which reopen a form that has
        // been scrolled out of view instead of closing it. Matches the minimise shortcut.
        if (typeof App.TicketViewForm !== 'undefined' && typeof App.TicketViewForm.hideAllForms === 'function') {
            App.TicketViewForm.hideAllForms();

            return;
        }

        this.form.addClass('sp:hidden');
    }

    private expandForm(): void {
        if (! this.form) {
            return;
        }

        const maxAllowedHeight = this.getMaxAllowedHeight();
        const height = maxAllowedHeight ? (maxAllowedHeight + 'px') : this.defaultMaxHeight;

        this.form.css({
            'height': height,
            'max-height': height
        });

        this.toggleExpandControls(true);
    }

    private compressForm(): void {
        if (! this.form) {
            return;
        }

        const storedHeight = this.getStoredHeight();

        // Restore stored height if available.
        if (storedHeight && storedHeight >= this.minHeight) {
            this.setHeight(storedHeight);
        } else {
            this.form.css({
                'height': '',
                'max-height': ''
            });
        }

        this.toggleExpandControls(false);
    }

    private startResize(e: JQuery.TriggeredEvent): void {
        if (this.isResizing || ! this.form) {
            return;
        }

        // Remember which finger started the drag, so that a second one touching down (or the first
        // being lifted while another is still on screen) can't hijack it and jump the height.
        const started = (e.originalEvent as TouchEvent | undefined)?.changedTouches?.[0];
        this.touchId = started ? started.identifier : null;

        const pageY = this.getEventPageY(e);

        if (pageY === null) {
            this.touchId = null;

            return;
        }

        this.isResizing = true;
        this.startY = pageY;
        this.startHeight = this.form.outerHeight() as number;

        this.form.addClass('sp-resizing');
        $('body').addClass('sp-resize-cursor');
    }

    private handleMove(e: JQuery.TriggeredEvent): void {
        const pageY = this.getEventPageY(e);

        if (! this.isResizing || pageY === null) {
            return;
        }

        if (e.type === 'mousemove') {
            e.preventDefault();
        }

        const deltaY = this.startY - pageY;
        let newHeight = Math.max(this.minHeight, this.startHeight + deltaY);

        this.setHeight(newHeight);
    }

    /**
     * Page position of a mouse or touch event. jQuery doesn't copy pageY onto touch events, so we
     * have to read the touch point we're tracking from the original event.
     */
    private getEventPageY(e: JQuery.TriggeredEvent): number | null {
        const original = e.originalEvent as TouchEvent | undefined;

        if (original && original.changedTouches) {
            const touch = this.findTrackedTouch(original);

            return touch ? touch.pageY : null;
        }

        return typeof e.pageY === 'number' ? e.pageY : null;
    }

    /**
     * The touch point that started the drag, looked up by identifier. A move only reports the
     * finger that moved in changedTouches, so fall back to the full list when it isn't in there.
     */
    private findTrackedTouch(event: TouchEvent): Touch | null {
        const lists = [event.changedTouches, event.touches];

        for (let list = 0; list < lists.length; list++) {
            const touches = lists[list];

            if (! touches) {
                continue;
            }

            for (let i = 0; i < touches.length; i++) {
                if (this.touchId === null || touches[i].identifier === this.touchId) {
                    return touches[i];
                }
            }
        }

        return null;
    }

    private setHeight(newHeight: number): void {
        if (! this.form) {
            return;
        }

        // Calculate max allowed height.
        const maxAllowedHeight = this.getMaxAllowedHeight();
        if (maxAllowedHeight) {
            newHeight = Math.min(newHeight, maxAllowedHeight);
        }

        this.form.css({
            'height': newHeight + 'px',
            'max-height': maxAllowedHeight ? (maxAllowedHeight + 'px') : this.defaultMaxHeight
        });

        this.toggleExpandControls(newHeight === maxAllowedHeight);
    }

    private stopResize(): void {
        if (! this.isResizing) {
            return;
        }

        this.isResizing = false;

        if (this.form) {
            this.setStoredHeight(this.form.outerHeight() as number);
            this.form.removeClass('sp-resizing');
        }

        $('body').removeClass('sp-resize-cursor');
        this.startY = 0;
        this.startHeight = 0;
        this.touchId = null;
    }

    private getMaxAllowedHeight(): number | null {
        if (! this.form) {
            return null;
        }

        const $content = this.form.closest('#content');

        if ($content.length) {
            const contentHeight = $content.height() as number;
            const quickActionsHeight = $('.sp-quick-actions').outerHeight() || 0;

            return contentHeight - quickActionsHeight;
        }

        return null;
    }

    private getStoredHeight(): number | null {
        try {
            const stored = localStorage.getItem(this.storageKey);
            return stored ? parseInt(stored, 10) : null;
        } catch (e) {
            return null;
        }
    }

    private setStoredHeight(height: number): void {
        try {
            localStorage.setItem(this.storageKey, height.toString());
        } catch (e) {
            // Silently fail if localStorage is not available.
        }
    }

    private getStoredIsSticky(): boolean {
        try {
            const stored = localStorage.getItem(this.stickyStorageKey);
            if (stored !== null) {
                return stored === 'true';
            }
        } catch (e) {
            // Fall through to the default below.
        }

        return this.defaultIsSticky();
    }

    /**
     * Default to sticky, unless the form at its minimum height would take up too much of the space
     * available to the ticket. The operator can still pin it themselves if they want to.
     */
    private defaultIsSticky(): boolean {
        const maxAllowedHeight = this.getMaxAllowedHeight();

        if (maxAllowedHeight === null) {
            return true;
        }

        // Touch devices need more room before it's worth pinning, as the virtual keyboard eats into
        // the viewport. This keeps it off phones, while still allowing it on a tablet held upright.
        const minimumMultiple = window.matchMedia('(pointer: coarse)').matches ? 3 : 2;

        return maxAllowedHeight >= this.minHeight * minimumMultiple;
    }

    private setStoredIsSticky(isSticky: boolean): void {
        try {
            localStorage.setItem(this.stickyStorageKey, isSticky.toString());
        } catch (e) {
            // Silently fail if localStorage is not available.
        }
    }
}

declare const App: any;

